/** @param {Readonly<Record<string, string>>} slugs @param {string} key */
const slugFrom = (slugs, key) => (Object.hasOwn(slugs, key) ? slugs[key] : '');

/**
 * O slug do logo do provedor, ou `''` quando ele não tem logo aqui.
 * `providerIconSlug('xai')` → `'grok'`; `providerIconSlug('meu-provedor')` → `''`
 * @param {string} provider id do provedor no catálogo
 * @returns {string}
 */
export function providerIconSlug(provider) {
  return slugFrom(PROVIDER_SLUGS, provider);
}

/**
 * O slug do logo do fabricante pelo prefixo do id do modelo, ou `''` sem
 * prefixo ou sem logo.
 * `vendorIconSlug('meta-llama/llama-5-scout')` → `'meta'`; `vendorIconSlug('gpt-5')` → `''`
 * @param {string} modelId id do modelo no catálogo
 * @returns {string}
 */
export function vendorIconSlug(modelId) {
  /* O OpenRouter tem apelidos com `~` na frente (`~openai/gpt-latest`): o
     fabricante é o mesmo do id sem o til. */
  const id = String(modelId).replace(/^~/, '');
  const cut = id.indexOf('/');
  return cut > 0 ? slugFrom(VENDOR_SLUGS, id.slice(0, cut)) : '';
}

/**
 * Os slugs que os mapas usam, para o teste conferir que todos têm caminho.
 * @returns {string[]}
 */
export function mappedIconSlugs() {
  return [...new Set([...Object.values(PROVIDER_SLUGS), ...Object.values(VENDOR_SLUGS)])];
}

export const MONOGRAM_SLOTS = 6;

/**
 * As letras do monograma: as iniciais das duas primeiras palavras do nome; numa
 * palavra só, a inicial e a próxima maiúscula, se houver ("OpenAI" → "OA").
 * `monogramLetters('OpenAI Codex')` → `'OC'`; `monogramLetters('opencode-go')` → `'OG'`; `monogramLetters('commandcode')` → `'C'`
 * @param {string} name nome do provedor (ou o id cru)
 * @returns {string}
 */
export function monogramLetters(name) {
  const words = String(name).split(/[^\p{L}\p{N}]+/u).filter(Boolean);
  if (!words.length) return '?';
  if (words.length > 1) return (words[0][0] + words[1][0]).toUpperCase();
  const [first, ...rest] = [...words[0]];
  const upper = rest.find((char) => char !== char.toLowerCase());
  return (first + (upper || '')).toUpperCase();
}

/**
 * O lugar da paleta (1 a `MONOGRAM_SLOTS`) do provedor: o mesmo id dá sempre a mesma cor.
 * `monogramSlot('xai') === monogramSlot('xai')` → `true`
 * @param {string} provider
 * @returns {number}
 */
export function monogramSlot(provider) {
  /* FNV-1a com a mistura final do murmur3: um `× 31` simples é ≡ 1 mod 6, vira a
     soma dos códigos e junta as cores dos provedores parecidos. */
  let hash = 0x811c9dc5;
  for (const char of String(provider)) hash = Math.imul(hash ^ /** @type {number} */ (char.codePointAt(0)), 0x01000193) >>> 0;
  hash = Math.imul(hash ^ (hash >>> 16), 0x85ebca6b) >>> 0;
  hash = (hash ^ (hash >>> 13)) >>> 0;
  return (hash % MONOGRAM_SLOTS) + 1;
}

/** @param {string} text */
const escapeText = (text) => text.replace(/[&<>"]/g, (char) => `&#${char.charCodeAt(0)};`);

/** @param {BrandPath} entry */
const pathTag = (entry) => (typeof entry === 'string' ? `<path d="${entry}"/>` : `<path d="${entry[0]}" fill-opacity="${entry[1]}"/>`);

/**
 * O logo de um slug do Lobe, na cor do texto, ou `''` para slug desconhecido.
 * `brandIcon('openai')` → `'<svg class="icon provider-icon" data-brand="openai" …'`
 * @param {string} slug
 * @returns {string}
 */
export function brandIcon(slug) {
  if (!Object.hasOwn(LOBE_ICONS, slug)) return '';
  const {box = '0 0 24 24', nonzero, paths} = LOBE_ICONS[slug];
  const rule = nonzero ? '' : ' fill-rule="evenodd"';
  return `<svg class="icon provider-icon" data-brand="${slug}" viewBox="${box}" fill="currentColor"${rule} aria-hidden="true">${paths.map(pathTag).join('')}</svg>`;
}

/** @param {string} key id que escolhe a cor @param {string} name nome de onde saem as letras */
const monogram = (key, name) => `<span class="provider-mono" data-slot="${monogramSlot(key)}" aria-hidden="true">${escapeText(monogramLetters(name))}</span>`;

/**
 * O logo do provedor, na cor do texto; sem logo, o monograma com as letras do
 * nome numa cor estável. `name` é o nome mostrado (o id cru, sem nome conhecido).
 * `providerIcon('anthropic')` → `'<svg class="icon provider-icon" data-brand="anthropic" …'`
 * `providerIcon('meu-provedor')` → `'<span class="provider-mono" data-slot="…" aria-hidden="true">MP</span>'`
 * @param {string} provider id do provedor no catálogo
 * @param {string} [name]
 * @returns {string}
 */
export function providerIcon(provider, name = provider) {
  return brandIcon(providerIconSlug(provider)) || monogram(provider, name);
}

/**
 * O logo do fabricante de um subgrupo, pelo prefixo do id de um modelo dele;
 * sem logo, o monograma do nome do fabricante.
 * `vendorIcon('x-ai/grok-5', 'xAI')` → `'<svg … data-brand="grok" …'`; `vendorIcon('sao10k/euryale', 'Sao10K')` → monograma "SK"
 * @param {string} modelId id de um modelo do subgrupo
 * @param {string} vendor nome do fabricante
 * @returns {string}
 */
export function vendorIcon(modelId, vendor) {
  return brandIcon(vendorIconSlug(modelId)) || monogram(vendor, vendor);
}

/**
 * O logo do modelo em uso, para o indicador do composer: o do fabricante pelo
 * prefixo do id (o OpenRouter serve vários) e, sem ele, o do provedor; `''`
 * sem provedor.
 * `choiceIcon('openrouter', 'deepseek/deepseek-v4')` → `'<svg … data-brand="deepseek" …'`; `choiceIcon('anthropic', '')` → `'<svg … data-brand="anthropic" …'`
 * @param {string} provider id do provedor no catálogo
 * @param {string} modelId id do modelo no catálogo
 * @param {string} [name] nome mostrado do provedor
 * @returns {string}
 */
export function choiceIcon(provider, modelId, name = provider) {
  if (!provider) return '';
  return brandIcon(vendorIconSlug(modelId)) || providerIcon(provider, name);
}
